// Register Service Worker for offline support
if('serviceWorker' in navigator){
  const swCode=`
const CACHE='gallery-v1';
const SHELL=['/my-gallery/','/my-gallery/index.html','/my-gallery/static/js/main.9081ee57.js','/my-gallery/static/css/main.e6c13ad2.css'];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(SHELL))));
self.addEventListener('fetch',e=>{
  e.respondWith(caches.match(e.request).then(cached=>{
    if(cached)return cached;
    return fetch(e.request).then(res=>{
      if(!res||res.status!==200||res.type!=='basic')return res;
      const clone=res.clone();
      caches.open(CACHE).then(c=>c.put(e.request,clone));
      return res;
    }).catch(()=>caches.match('/my-gallery/index.html'));
  }));
});`;
  try{
    const blob=new Blob([swCode],{type:'application/javascript'});
    const url=URL.createObjectURL(blob);
    navigator.serviceWorker.register(url)
      .then(()=>console.log('Gallery cached for offline use'))
      .catch(()=>{});
  }catch(e){}
}

